window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7b8368e529ec6a03"]={"versions": [{"id": "FIG-7b8368e529ec6a03", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadablePackageElement</code>: Übergeordnete Basisklasse für bereitstellbare Modellelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadablePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>.</li>\n<li><code>PersistencyRedundancyCrc</code>: Konkrete Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String</code></li>\n<li><code>length: PositiveInteger</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Konkrete Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger</code></li>\n<li><code>n: PositiveInteger</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Manifest-Modellelemente für Adaptive AUTOSAR Persistency. <code>maximumAllowedSize</code> und <code>minimumSustainedSize</code> setzen Speicherplatzschranken. <code>updateStrategy</code> ist ein Pflichtfeld. Für Redundanzmechanismen müssen bei CRC Algorithmenfamilie und Bitlänge, bei M-aus-N die Schwellenwerte m und n als positive Ganzzahlen zwingend angegeben werden.</p>"}, {"id": "FIG-52848a98d8600e4f", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadablePackageElement</code>: Übergeordnete Basisklasse für bereitstellbare Modellelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadablePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeKey</code></li>\n<li><code>persistencyRedundancyHandlingScopeDatabase</code></li>\n<li><code>persistencyRedundancyHandlingScopeFile</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String</code></li>\n<li><code>length: PositiveInteger</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger</code></li>\n<li><code>n: PositiveInteger</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Definiert verbindliche Manifest-Modellelemente für Adaptive AUTOSAR Persistency. Der Gültigkeitsbereich von Redundanzmechanismen kann über das optionale Attribut <code>scope</code> differenziert auf Schlüssel-, Datenbank- oder Dateiebene festgelegt werden. <code>updateStrategy</code> bleibt verpflichtend. Bei CRC und M-aus-N sind alle Attribute Pflichtfelder.</p>"}, {"id": "FIG-ceab076f99ac40b1", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadableExclusivePackageElement</code>: Übergeordnete Basisklasse für exklusiv bereitstellbare Paketelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadableExclusivePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeElement</code></li>\n<li><code>persistencyRedundancyHandlingScopeStorage</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Direkte Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger</code></li>\n<li><code>n: PositiveInteger</code></li>\n<li><code>PersistencyRedundancyChecksum</code> (kursiv/abstrakt): Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String</code></li>\n<li><code>length: PositiveInteger</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> ohne zusätzliche Attribute.</li>\n<li><code>PersistencyRedundancyHash</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> mit:</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellelemente zur Manifest-Modellierung der Persistenz. <code>PersistencyDeployment</code> ist nun als <code>UploadableExclusivePackageElement</code> klassifiziert. Die Redundanzabsicherung unterscheidet im Gültigkeitsbereich (<code>scope</code>) zwischen einzelnen Elementen (<code>persistencyRedundancyHandlingScopeElement</code>) und dem gesamten Speicher (<code>persistencyRedundancyHandlingScopeStorage</code>). Prüfsummenverfahren werden über <code>PersistencyRedundancyChecksum</code> generalisiert, wodurch neben CRC auch kryptografische Hash-Verfahren (<code>PersistencyRedundancyHash</code>) mit optionalem Initialisierungsvektor konfiguriert werden können.</p>"}, {"id": "FIG-dbcb6bf4be2900a9", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadableExclusivePackageElement</code>: Übergeordnete Basisklasse für exklusiv bereitstellbare Paketelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadableExclusivePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum</code></li>\n<li><code>version: StrongRevisionLabelString [0..1]</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeElement</code></li>\n<li><code>persistencyRedundancyHandlingScopeStorage</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Direkte Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger</code></li>\n<li><code>n: PositiveInteger</code></li>\n<li><code>PersistencyRedundancyChecksum</code> (kursiv/abstrakt): Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String</code></li>\n<li><code>length: PositiveInteger</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> ohne zusätzliche Attribute.</li>\n<li><code>PersistencyRedundancyHash</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> mit:</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellelemente zur Manifest-Modellierung der Persistenz. Die Versionierung des Persistenz-Deployments kann optional über <code>version</code> als <code>StrongRevisionLabelString</code> deklariert werden, um Migrations- und Update-Vorgänge deterministisch zu unterstützen.</p>"}, {"id": "FIG-b123fcba80403164", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadableExclusivePackageElement</code>: Übergeordnete Basisklasse für exklusiv bereitstellbare Paketelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadableExclusivePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code></li>\n<li><code>version: StrongRevisionLabelString [0..1]</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeElement</code></li>\n<li><code>persistencyRedundancyHandlingScopeStorage</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Direkte Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger [0..1]</code></li>\n<li><code>n: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyChecksum</code> (kursiv/abstrakt): Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String [0..1]</code></li>\n<li><code>length: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> ohne zusätzliche Attribute.</li>\n<li><code>PersistencyRedundancyHash</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> mit:</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellelemente zur Manifest-Modellierung der Persistenz. Wesentliche Konfigurationsparameter wurden auf optionale Kardinalität <code>[0..1]</code> umgestellt: <code>updateStrategy</code> in <code>PersistencyDeployment</code>, <code>m</code> und <code>n</code> in <code>PersistencyRedundancyMOutOfN</code> sowie <code>algorithmFamily</code> und <code>length</code> in <code>PersistencyRedundancyChecksum</code>. Modellierer können diese Werte weglassen, sofern Standardeinstellungen oder plattformspezifische Vorgaben greifen.</p>"}, {"id": "FIG-df7e02f4f4ea15ef", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadableExclusivePackageElement</code>: Übergeordnete Basisklasse für exklusiv bereitstellbare Paketelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadableExclusivePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code></li>\n<li><code>version: StrongRevisionLabelString [0..1]</code></li>\n<li><code>PortInterface::PersistencyCollectionLevelUpdateStrategyEnum</code> («enumeration»):</li>\n<li><code>keepExisting</code></li>\n<li><code>delete</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeElement</code></li>\n<li><code>persistencyRedundancyHandlingScopeStorage</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Direkte Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger [0..1]</code></li>\n<li><code>n: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyChecksum</code> (kursiv/abstrakt): Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String [0..1]</code></li>\n<li><code>length: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> ohne zusätzliche Attribute.</li>\n<li><code>PersistencyRedundancyHash</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> mit:</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellelemente zur Manifest-Modellierung der Persistenz. Wesentliche Konfigurationsparameter wurden auf optionale Kardinalität <code>[0..1]</code> umgestellt: <code>updateStrategy</code> in <code>PersistencyDeployment</code>, <code>m</code> und <code>n</code> in <code>PersistencyRedundancyMOutOfN</code> sowie <code>algorithmFamily</code> und <code>length</code> in <code>PersistencyRedundancyChecksum</code>. Modellierer können diese Werte weglassen, sofern Standardeinstellungen oder plattformspezifische Vorgaben greifen.</p>"}, {"id": "FIG-2f756ec30088887d", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadableExclusivePackageElement</code>: Übergeordnete Basisklasse für exklusiv bereitstellbare Paketelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadableExclusivePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code></li>\n<li><code>version: StrongRevisionLabelString [0..1]</code></li>\n<li><code>PortInterface::PersistencyCollectionLevelUpdateStrategyEnum</code> («enumeration»):</li>\n<li><code>keepExisting</code></li>\n<li><code>delete</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über Komposition <code>+redundancyHandling 0..*</code> aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeElement</code></li>\n<li><code>persistencyRedundancyHandlingScopeStorage</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Direkte Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger [0..1]</code></li>\n<li><code>n: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyChecksum</code> (kursiv/abstrakt): Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String [0..1]</code></li>\n<li><code>length: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> ohne zusätzliche Attribute.</li>\n<li><code>PersistencyRedundancyHash</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> mit:</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellelemente zur Manifest-Modellierung der Persistenz. Wesentliche Konfigurationsparameter wurden auf optionale Kardinalität <code>[0..1]</code> umgestellt: <code>updateStrategy</code> in <code>PersistencyDeployment</code>, <code>m</code> und <code>n</code> in <code>PersistencyRedundancyMOutOfN</code> sowie <code>algorithmFamily</code> und <code>length</code> in <code>PersistencyRedundancyChecksum</code>. Modellierer können diese Werte weglassen, sofern Standardeinstellungen oder plattformspezifische Vorgaben greifen.</p>"}, {"id": "FIG-510b20885f369646", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodellierung der Persistenz-Bereitstellung (Persistency Deployment) in der AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die abstrakte Basisklasse für Bereitstellungsbeschreibungen persistenter Daten und deren Konfiguration zur Redundanz- und Integritätssicherung.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entitäten sind:</p>\n<ul class=\"fig-list\">\n<li><code>UploadableExclusivePackageElement</code>: Übergeordnete Basisklasse für exklusiv bereitstellbare Paketelemente.</li>\n<li><code>PersistencyDeployment</code> (kursiv/abstrakt): Spezialisierung von <code>UploadableExclusivePackageElement</code> mit Attributen:</li>\n<li><code>maximumAllowedSize: PositiveUnlimitedInteger [0..1]</code></li>\n<li><code>minimumSustainedSize: PositiveInteger [0..1]</code></li>\n<li><code>updateStrategy: PersistencyCollectionLevelUpdateStrategyEnum [0..1]</code></li>\n<li><code>version: StrongRevisionLabelString [0..1]</code></li>\n<li><code>PersistencyCollectionLevelUpdateStrategyEnum</code> («enumeration»):</li>\n<li><code>keepExisting</code></li>\n<li><code>delete</code></li>\n<li><code>PersistencyRedundancyHandling</code> (kursiv/abstrakt): Über splittbare Komposition (<code>«atpSplitable»</code>, Rolle <code>+redundancyHandling 0..*</code>) aggregiert durch <code>PersistencyDeployment</code>, mit Attribut:</li>\n<li><code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code></li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code> («enumeration»):</li>\n<li><code>persistencyRedundancyHandlingScopeElement</code></li>\n<li><code>persistencyRedundancyHandlingScopeStorage</code></li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Direkte Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>m: PositiveInteger [0..1]</code></li>\n<li><code>n: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyChecksum</code> (kursiv/abstrakt): Spezialisierung von <code>PersistencyRedundancyHandling</code> mit:</li>\n<li><code>algorithmFamily: String [0..1]</code></li>\n<li><code>length: PositiveInteger [0..1]</code></li>\n<li><code>PersistencyRedundancyCrc</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> ohne zusätzliche Attribute.</li>\n<li><code>PersistencyRedundancyHash</code>: Spezialisierung von <code>PersistencyRedundancyChecksum</code> mit:</li>\n<li><code>initializationVectorLength: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenzabläufe. Instanzen der Subklassen von <code>PersistencyRedundancyHandling</code> werden zur Laufzeit oder Deployment-Zeit von der Persistenz-Laufzeitumgebung herangezogen, um Integritätsprüfungen (CRC) bzw. Redundanzmechanismen (M-aus-N) auf persistenten Datenbeständen auszuführen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellelemente zur Manifest-Modellierung der Persistenz. Wesentliche Konfigurationsparameter wurden auf optionale Kardinalität <code>[0..1]</code> umgestellt: <code>updateStrategy</code> in <code>PersistencyDeployment</code>, <code>m</code> und <code>n</code> in <code>PersistencyRedundancyMOutOfN</code> sowie <code>algorithmFamily</code> und <code>length</code> in <code>PersistencyRedundancyChecksum</code>. Modellierer können diese Werte weglassen, sofern Standardeinstellungen oder plattformspezifische Vorgaben greifen.</p>"}], "trans": [{"from": "FIG-7b8368e529ec6a03", "to": "FIG-52848a98d8600e4f", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyRedundancyHandling</code>: Attribut <code>scope: PersistencyRedundancyHandlingScopeEnum [0..1]</code> hinzugefügt.</li>\n<li>Aufzählung <code>PersistencyRedundancyHandlingScopeEnum</code> mit den Literalen <code>persistencyRedundancyHandlingScopeKey</code>, <code>persistencyRedundancyHandlingScopeDatabase</code> und <code>persistencyRedundancyHandlingScopeFile</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-52848a98d8600e4f", "to": "FIG-ceab076f99ac40b1", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyDeployment</code>: Spezialisierung von <code>UploadablePackageElement</code> auf <code>UploadableExclusivePackageElement</code> geändert.</li>\n<li>Vererbungshierarchie für Prüfsummen umstrukturiert: Abstrakte Zwischenklasse <code>PersistencyRedundancyChecksum</code> (erbt von <code>PersistencyRedundancyHandling</code>) mit den Attributen <code>algorithmFamily: String</code> und <code>length: PositiveInteger</code> eingeführt.</li>\n<li><code>PersistencyRedundancyCrc</code>: Erbt nun von <code>PersistencyRedundancyChecksum</code> statt direkt von <code>PersistencyRedundancyHandling</code>; eigene Attribute nach oben verschoben.</li>\n<li>Klasse <code>PersistencyRedundancyHash</code> (erbt von <code>PersistencyRedundancyChecksum</code>) mit Attribut <code>initializationVectorLength: PositiveInteger [0..1]</code> neu eingeführt.</li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code>: Literale ersetzt durch <code>persistencyRedundancyHandlingScopeElement</code> und <code>persistencyRedundancyHandlingScopeStorage</code>.</li>\n</ul>"}, {"from": "FIG-ceab076f99ac40b1", "to": "FIG-dbcb6bf4be2900a9", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyDeployment</code>: Attribut <code>version: StrongRevisionLabelString [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-dbcb6bf4be2900a9", "to": "FIG-b123fcba80403164", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>PersistencyDeployment</code>: Multiplizität des Attributs <code>updateStrategy</code> von <code>1</code> auf <code>[0..1]</code> gelockert.</li>\n<li><code>PersistencyRedundancyMOutOfN</code>: Multiplizitäten der Attribute <code>m</code> und <code>n</code> jeweils von <code>1</code> auf <code>[0..1]</code> gelockert.</li>\n<li><code>PersistencyRedundancyChecksum</code>: Multiplizitäten der Attribute <code>algorithmFamily</code> und <code>length</code> jeweils von <code>1</code> auf <code>[0..1]</code> gelockert.</li>\n</ul>"}, {"from": "FIG-b123fcba80403164", "to": "FIG-df7e02f4f4ea15ef", "fr": "R22-11", "tr": "R23-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Aufzählung <code>PortInterface::PersistencyCollectionLevelUpdateStrategyEnum</code> mit den Literalen <code>keepExisting</code> und <code>delete</code> im Diagramm als eigenständiger Block explizit dargestellt.</li>\n</ul>"}, {"from": "FIG-df7e02f4f4ea15ef", "to": "FIG-2f756ec30088887d", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>PortInterface::PersistencyCollectionLevelUpdateStrategyEnum</code>: Abschnittsüberschrift <code>literals</code> über den Literalen ergänzt.</li>\n<li><code>PersistencyRedundancyHandlingScopeEnum</code>: Abschnittsüberschrift <code>literals</code> über den Literalen ergänzt.</li>\n</ul>"}, {"from": "FIG-2f756ec30088887d", "to": "FIG-510b20885f369646", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Komposition von <code>PersistencyDeployment</code> zu <code>PersistencyRedundancyHandling</code> (<code>+redundancyHandling</code>): Stereotyp <code>«atpSplitable»</code> ergänzt.</li>\n<li><code>PersistencyCollectionLevelUpdateStrategyEnum</code>: Namespace-Präfix <code>PortInterface::</code> im Klassenkopf entfernt.</li>\n</ul>"}]};
